  populations: Object.freeze([
    "Professional / Elite",
    "Collegiate",
    "Youth / Adolescent",
    "Adult / Recreational",
    "Female Athletes",
    "Male Athletes",
    "Injured Athletes",
    "Healthy Athletes",
    "Mixed / Unspecified",
  ]),
  studyDesigns: Object.freeze([
    "Systematic Review / Meta-analysis",
    "Randomized Controlled Trial",
    "Cohort Study",
    "Cross-sectional Study",
