import sqlite3, os, json, re
from collections import Counter
c = sqlite3.connect(os.path.expanduser('~/.local/share/fireflies-pp-cli/data.db'))
rows = [json.loads(d) for (d,) in c.execute("select data from transcripts")]
GEN = re.compile(r'^(speaker\s*\d+|unknown|)$', re.I)
ME = re.compile(r'rash', re.I)
t = Counter()
for r in rows:
    link = (r.get('meeting_link') or '').lower()
    kind = 'teams' if 'teams' in link else 'zoom' if 'zoom' in link else 'meet' if 'meet.google' in link else 'no link (upload/in-person)'
    sents = r.get('sentences') or []
    snames = {str(s.get('speaker_name') or '').strip() for s in sents if isinstance(s, dict)}
    named = {n for n in snames if not GEN.match(n) and not ME.search(n)}
    spk = {str((s or {}).get('name') or '').strip() for s in (r.get('speakers') or []) if isinstance(s, dict)}
    spk_named = {n for n in spk if not GEN.match(n) and not ME.search(n)}
    has_sents = bool(sents)
    who = bool(named or spk_named)
    t[(kind, 'has sentences' if has_sents else 'no sentences', 'named other' if who else 'no named other')] += 1
for k, v in sorted(t.items(), key=lambda kv: -kv[1]):
    print(v, k)
# recent volume
recent = [r for r in rows if (r.get('dateString') or '') >= '2026-07-01']
print('since 2026-07-01:', len(recent))
rt = Counter()
for r in recent:
    sents = r.get('sentences') or []
    named = {str(s.get('speaker_name') or '').strip() for s in sents if isinstance(s, dict)}
    named = {n for n in named if not GEN.match(n) and not ME.search(n)}
    spk = {str((s or {}).get('name') or '').strip() for s in (r.get('speakers') or []) if isinstance(s, dict)}
    named |= {n for n in spk if not GEN.match(n) and not ME.search(n)}
    rt['named other' if named else 'no named other'] += 1
print('recent:', dict(rt))

