#!/usr/bin/env python3
"""Apply Eric's rule to his C labels: a completed surgery counts only if it was within 12 months
of the note. No API calls.

    python recent_surgery.py --sheet   # private/recent_sheet.md: the C-labelled notes, a code hint each
    python recent_surgery.py --count   # read Eric's Y/N and report the final count

The hint is a code guess from time phrases; Eric's Y/N is the answer. PHI stays in private/.
"""

from __future__ import annotations

import argparse
import os
import re
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE))
import surgery  # noqa: E402

SHEET = surgery.PRIVATE / "recent_sheet.md"
WORDS = {"a": 1, "an": 1, "one": 1, "two": 2, "three": 3, "four": 4, "five": 5, "six": 6,
         "seven": 7, "eight": 8, "nine": 9, "ten": 10, "eleven": 11, "twelve": 12}
NUM = r"(\d+(?:\.\d+)?|a|an|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve)"


def note_dates() -> dict:
    import pandas as pd
    root = surgery.ath_medicine()
    df = pd.read_csv(root / "Baylor Medical Diagnostics Report (June 1, 2025 - May 31, 2026).csv",
                     encoding="utf-8", usecols=["DiagnosticDate"])
    return {int(i): str(d)[:10] for i, d in df["DiagnosticDate"].items()}


def to_num(token: str) -> float:
    return WORDS.get(token.lower(), None) or float(token)


def hint(note: str, note_date: str) -> tuple[str, str]:
    """Return (guess, reason). guess is 'within', 'older' or 'unclear'."""
    text = note.lower()
    year = int(note_date[:4]) if note_date[:4].isdigit() else None
    m = re.search(NUM + r"\s*(weeks?|wks?|months?|mos?)\s*(?:post|after|out|since|s/p|removed from)", text)
    if m:
        months = to_num(m.group(1)) / (4.3 if m.group(2).startswith("w") else 1)
        return ("within" if months <= 12 else "older", f"'{m.group(0)}'")
    m = re.search(NUM + r"\s*(years?|yrs?)\s*(?:ago|post|prior|out|since|removed)", text)
    if m:
        return ("within" if to_num(m.group(1)) < 1 else "older", f"'{m.group(0)}'")
    if re.search(r"high school|in the past|years ago|as a (?:child|kid)|growing up|middle school", text):
        return ("older", "phrase suggests long ago")
    years = [int(y) for y in re.findall(r"\b(20[0-2]\d)\b", text)]
    if years and year:
        gap = year - min(years)
        if gap >= 2:
            return ("older", f"mentions {min(years)} (note {year})")
        if gap <= 0:
            return ("within", f"mentions {min(years)} (note {year})")
        return ("unclear", f"mentions {min(years)}, note {year}: check month")
    if re.search(r"post-?op|status post|s/p|recovering from|rehab(?:bing)? from|since (?:his|her) surgery", text):
        return ("within", "current post-op / rehab language")
    return ("unclear", "no time phrase found")


def c_rows() -> list[dict]:
    labels = surgery.eric_labels()
    rows = {r["row"]: r for r in surgery.load_rows()}
    dates = note_dates()
    return [dict(rows[i], date=dates.get(i, "?")) for i in sorted(labels) if labels[i] == "C"]


def sheet() -> None:
    rows = c_rows()
    lines = ["# Completed surgeries: within 12 months of the note? (PHI: keep local, never commit)", "",
             "Rule (Eric, 2026-09-21): count a surgery only if it happened within 12 months before",
             "the note date. Put **Y** or **N** after `Within 12 months:`. The hint is a code guess.", ""]
    for n, r in enumerate(rows, 1):
        guess, why = hint(r["note"], r["date"])
        lines += [f"## {n}. row {r['row']} — note dated {r['date']}", "",
                  f"*Code hint: **{guess}** ({why})*", "",
                  r["note"].replace("\n", " "), "", "Within 12 months: ", ""]
    SHEET.write_text("\n".join(lines), encoding="utf-8")
    from collections import Counter
    print(f"wrote {SHEET} ({len(rows)} notes); hints:",
          dict(Counter(hint(r['note'], r['date'])[0] for r in rows)))


def count() -> None:
    text = SHEET.read_text(encoding="utf-8")
    picks = re.findall(r"## \d+\. row (\d+).*?Within 12 months:[ \t]*([YNyn]?)", text, flags=re.S)
    rows = {r["row"]: r for r in c_rows()}
    yes = sum(p.upper() == "Y" for _, p in picks)
    blank = sum(not p for _, p in picks)
    agree = sum(p and (p.upper() == "Y") == (hint(rows[int(i)]["note"], rows[int(i)]["date"])[0] == "within")
                for i, p in picks if hint(rows[int(i)]["note"], rows[int(i)]["date"])[0] != "unclear")
    print(f"C-labelled notes: {len(picks)} | within 12 months (Y): {yes} | N: {len(picks) - yes - blank} | blank: {blank}")
    print(f"code hint agreed with Eric on {agree} of the notes where it made a guess")


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    group = parser.add_mutually_exclusive_group(required=True)
    group.add_argument("--sheet", action="store_true")
    group.add_argument("--count", action="store_true")
    args = parser.parse_args()
    sheet() if args.sheet else count()

