"""Read-only git status sweep across DEV repos. Prints only repos that are dirty, ahead, or unusual."""
import os, subprocess
ROOT = r"C:\Users\eric_rash\Desktop\DEV"
bases = [ROOT, os.path.join(ROOT, "Football"), os.path.join(ROOT, "SpecialRequests")]
home = os.path.expanduser("~")
extra = [os.path.join(home, ".claude"), os.path.join(home, ".claude", "skills"), os.path.join(home, ".claude", "global-memory")]
repos = set()
for b in bases:
    if os.path.isdir(os.path.join(b, ".git")):
        repos.add(b)
    for d in os.listdir(b):
        p = os.path.join(b, d)
        if os.path.isdir(p) and os.path.exists(os.path.join(p, ".git")):
            repos.add(p)
repos |= {e for e in extra if os.path.exists(os.path.join(e, ".git"))}
clean = 0
for r in sorted(repos):
    out = subprocess.run(["git", "-C", r, "status", "--porcelain", "-b"], capture_output=True, text=True, encoding="utf-8", errors="replace")
    lines = out.stdout.splitlines()
    head = lines[0] if lines else "?"
    dirty = [l for l in lines[1:] if l.strip()]
    if dirty or "ahead" in head or "no branch" in head or out.returncode:
        print(f"{os.path.relpath(r, home)} | {head} | {len(dirty)} changed" + (f" | err {out.stderr.strip()[:80]}" if out.returncode else ""))
    else:
        clean += 1
print(f"total repos {len(repos)}, clean+synced {clean}")

